/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/

/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

SInt16 sio_uart_ctrl_tx_drain_t (Sio_Uart sio_uart , Sio_Timeout timeout)
{
  #define IS_THRE    (sio_uart->uart_reg[ULSR] & BIT_THRE)
  #define IS_WAIT_OK  sio_uart_wait_tx_ready (sio_uart , timeout)

  return  IS_THRE || IS_WAIT_OK ? SIO_OK : SIO_TIMEOUT ;

  #undef  IS_WAIT_OK
  #undef  IS_THRE
}

